raw:
{
  "spells": [
    {
      "id": "spell_water_01",
      "theory": "凝露术将魔力铺成极薄的凉层附在杯壁外侧，使流经的空气降温，水汽便聚成细珠滑入杯中。凝出速度受当时空气湿度限制，干燥处只能得到潮痕。魔力只作用于杯壁附近，不会凭空生水，也不能让水向上流。",
      "casting": "食指与中指并拢，沿杯壁外沿画一道向下的弧线，同时缓缓呼气，使凉层均匀铺开。",
      "failure": "杯壁只出现一片雾痕，迟迟不聚成水滴；若魔力送得过急，凉层会突然散开，杯外结出薄霜而杯内依旧干燥。",
      "counters": [
        "用干布擦去杯壁凉层，水汽便不再附着。",
        "将杯子移到通风处，空气流动加快，凝出的水珠会减少。"
      ],
      "socialConsequences": "河谷乡民在井边或船头用这法术接取少量饮水，常请同行者见证杯子的归属，以免有人事后争抢。客栈伙计愿意为付了茶钱的客人凝一杯，但不会替陌生人反复凝水，因为湿气重时杯壁容易留下水渍。走远路的人会自己带杯，借他人器皿前先问过主人，凝出的水通常当场喝掉，不带走。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时水珠大小不一，杯壁外侧常留下成片湿痕。",
        "熟练后能控制凉层范围，使水珠沿杯壁内侧滑落。",
        "更熟练者可在半满杯中凝水而不溅出，速度仍受湿度限制。",
        "高熟练度下凉层均匀，杯外几乎不结霜，出水量仍按环境湿度决定。"
      ]
    },
    {
      "id": "spell_water_02",
      "theory": "净水术把魔力送入水桶内部，使悬浮的泥沙、草屑和细小虫体彼此靠拢，再借桶壁的浅纹沉到底部。它只处理可见的悬浮污物，不能消除一切毒素，也分不出盐分与矿物。桶中若有油膜，魔力会先聚油，油反而更容易沾在桶沿。",
      "casting": "手掌平贴桶壁，拇指按住桶沿刻好的短横线，缓慢转动手腕，同时默数三息，等浑物沉底。",
      "failure": "浑物沉到一半又散开，整桶水变得比先前更浑；若魔力送得太猛，桶底会结出黏滑的泥膜，倒水时重新翻起。",
      "counters": [
        "搅动桶底使沉淀重新悬浮，净水效果便失去。",
        "向水中撒一把细沙，沙粒会打乱魔力聚拢的路径。"
      ],
      "socialConsequences": "港口厨工和河谷染坊常备净水术，但染坊只用来洗去浮尘，不指望它去掉染料。船主担心水手把净过的水当作绝对干净，延误更换存水，因此要求每次净水后仍要煮沸。井边汲水的人若替邻家净水，会先说明只能去浑，不能去毒，免得日后有人生病时归咎于施术者。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时浑物沉底不全，桶底常留下一层细泥。",
        "熟练后能控制沉淀范围，使清水与泥层分界较清楚。",
        "更熟练者可在倒水时稳住泥层，减少搅浑。",
        "高熟练度下沉淀紧密，桶壁浅纹内不残留明显污迹。"
      ]
    },
    {
      "id": "spell_water_03",
      "theory": "辨泉术向近处水源送出一缕极淡的魔力，借水中盐分与腐败气味对魔力的阻滞差异，在指腹上形成麻、涩、滑三种触感。它只能判断水源本身的咸淡与腐气，不能探出暗藏契约，也读不出水底是否埋有器物。活水与死水的触感差异明显，但水质相近时容易混淆。",
      "casting": "指尖轻触水面或浸湿的井绳，闭眼感受指腹上的麻涩滑，同时缓缓吸气，辨清气味来源。",
      "failure": "指腹只传来一片杂乱刺痛，无法分辨盐分与腐气；若水源过浅，魔力会沿湿泥散开，让人误以为整片河滩都可饮用。",
      "counters": [
        "用净水冲洗手指，残留触感便消失。",
        "将水样静置片刻再辨，悬浮物沉降后触感更清楚。"
      ],
      "socialConsequences": "河谷巡渠人用辨泉术检查支流是否被上游泡麻或倒污，常请乡约在旁记下结论，作为分水纠纷的凭据。城市水贩担心被当众判出咸涩，会主动请公会的人复辨。港口验水员只在货主同意时触碰船舱水样，若擅自辨出船上饮水腐坏，可能被船主视为窥探航运私事。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把泥腥误判为腐气，需要反复对照清水。",
        "熟练后能区分咸涩与腐败两种触感，仍受距离限制。",
        "更熟练者可在流动水中辨出轻微咸味，不致误判整条河。",
        "高熟练度下触感清晰，但只能判断水源本身，不附加其他探查。"
      ]
    }
  ]
}
